ml_job_commands:
PUT _ml/anomaly_detectors/rosetta_user_changed_geolocation_change
{
  "description": "Migré depuis ElastAlert (change) : User changed geolocation",
  "analysis_config": {
    "bucket_span": "24h",
    "detectors": [
      {
        "function": "rare",
        "by_field_name": "source.geo.country_name",
        "detector_description": "Valeur rare/inédite de source.geo.country_name — migré depuis la règle ElastAlert (change) « User changed geolocation »",
        "partition_field_name": "user.name"
      }
    ],
    "influencers": [
      "user.name",
      "source.geo.country_name"
    ]
  },
  "data_description": {
    "time_field": "@timestamp"
  }
}

PUT _ml/datafeeds/datafeed-rosetta_user_changed_geolocation_change
{
  "job_id": "rosetta_user_changed_geolocation_change",
  "indices": [
    "logs-*"
  ],
  "query": {
    "bool": {
      "filter": [
        {
          "term": {
            "event.category": "authentication"
          }
        }
      ]
    }
  }
}

POST _ml/anomaly_detectors/rosetta_user_changed_geolocation_change/_open

POST _ml/datafeeds/datafeed-rosetta_user_changed_geolocation_change/_start

