PUT _ml/anomaly_detectors/rosetta_spike_in_authentication_failures_spike
{
  "description": "Migré depuis ElastAlert (spike) : Spike in authentication failures",
  "analysis_config": {
    "bucket_span": "1h",
    "detectors": [
      {
        "function": "high_count",
        "detector_description": "Pic du volume d'événements — migré depuis la règle ElastAlert « Spike in authentication failures »",
        "partition_field_name": "source.ip",
        "custom_rules": [
          {
            "actions": [
              "skip_result"
            ],
            "conditions": [
              {
                "applies_to": "actual",
                "operator": "lt",
                "value": 50.0
              }
            ]
          }
        ]
      }
    ],
    "influencers": [
      "source.ip"
    ]
  },
  "data_description": {
    "time_field": "@timestamp"
  }
}

PUT _ml/datafeeds/datafeed-rosetta_spike_in_authentication_failures_spike
{
  "job_id": "rosetta_spike_in_authentication_failures_spike",
  "indices": [
    "logs-*"
  ],
  "query": {
    "bool": {
      "filter": [
        {
          "query": {
            "query_string": {
              "query": "event.outcome:failure"
            }
          }
        }
      ]
    }
  }
}

POST _ml/anomaly_detectors/rosetta_spike_in_authentication_failures_spike/_open

POST _ml/datafeeds/datafeed-rosetta_spike_in_authentication_failures_spike/_start
